# models
from statsmodels.tsa.holtwinters import ExponentialSmoothing, SimpleExpSmoothing, Holt
from statsmodels.tsa.statespace.sarimax import SARIMAX
from statsmodels.tsa.forecasting.stl import STLForecast
results={}
# ETS additive seasonal
for trend in [None,'add']:
    for seasonal in ['add','mul']:
        try:
            fit=ExponentialSmoothing(y, trend=trend, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit(optimized=True)
            fc=fit.forecast(3)
            results[f'ETS trend={trend} seas={seasonal}']=fc.iloc[-1]
        except Exception as e:
            print(e)
# SARIMA grid by AIC
best=[]
for order in itertools.product(range(3), range(2), range(3)):
    for seas in [(0,1,1,12),(1,0,0,12),(1,0,1,12),(0,0,1,12),(0,0,0,12)]:
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                mod=SARIMAX(y, order=order, seasonal_order=seas, trend='c', enforce_stationarity=False, enforce_invertibility=False)
                fit=mod.fit(disp=False)
                if np.isfinite(fit.aic):
                    best.append((fit.aic, order, seas, fit))
        except Exception as e:
            pass
best_sorted=sorted(best, key=lambda x:x[0])[:10]
